/**
 * SLWLRNR learning cards — finished content.
 *
 * Generated by export_to_web.py in the slwlrnr-cards project. Edit
 * there, not here: this file is overwritten on every export.
 *
 * NOTE ON THE PAYWALL. `access` is explicit per card, not derived
 * from array position. A paid card's essay, words and thread must
 * never reach an anonymous client — gate on the server, not in CSS.
 */

export type CardAccess = "free" | "paid";

export type CardCredit = {
  artist: string;
  work: string;
  date: string;
  medium: string;
  collection: string;
  /** Rights basis, printed on the card and the page. */
  rights: string;
  objectUrl: string;
};

export type GlossaryTerm = { term: string; definition: string };

export type LearnCard = {
  id: string;
  slug: string;
  /** Printed on the card. Stable across reordering. */
  number: string;
  strand: string;
  strandName: string;
  /** Strand accent colour, hex. */
  colour: string;
  title: string;
  subtitle: string;
  access: CardAccess;
  /** The activity. Safe to show to anyone — it is the hook. */
  invitation: string;
  /** PAID: paragraphs may contain <i> and <b>. */
  essay: string[];
  /** PAID */
  words: GlossaryTerm[];
  /** PAID */
  thread: string[];
  /** PAID */
  need: string;
  cross: string;
  credit: CardCredit;
  /** /public paths. */
  image: string;
  pdf: string;
};

