export const FREE_CARDS = LEARN_CARDS.filter((c) => c.access === "free");
export const PAID_CARDS = LEARN_CARDS.filter((c) => c.access === "paid");

export function cardBySlug(slug: string): LearnCard | undefined {
  return LEARN_CARDS.find((c) => c.slug === slug);
}

/**
 * Strip everything a non-subscriber must not receive. Use this on the
 * server before serialising a paid card to the client.
 */
export function publicView(card: LearnCard, entitled: boolean) {
  if (entitled || card.access === "free") return card;
  const { essay, words, thread, need, ...rest } = card;
  return { ...rest, essay: [], words: [], thread: [], need: "" };
}
